head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "chk": "",
        "brdId": "aaa",
        "prntId": "",
        "brdCtnt": "",
        "cmtDesc": "",
        "optCd": "",
        "tpCd": "",
        "creUsrId": "",
        "usrEml": "",
        "creDt": "",
        "updDt": "",
        "readKnt": "",
        "usrPwd": ""
    }, {
        "chk": "",
        "brdId": "bbb",
        "prntId": "",
        "brdCtnt": "",
        "cmtDesc": "",
        "optCd": "",
        "tpCd": "",
        "creUsrId": "",
        "usrEml": "",
        "creDt": "",
        "updDt": "",
        "readKnt": "",
        "usrPwd": ""
    }, {
        "chk": "",
        "brdId": "ccc",
        "prntId": "",
        "brdCtnt": "",
        "cmtDesc": "",
        "optCd": "",
        "tpCd": "",
        "creUsrId": "",
        "usrEml": "",
        "creDt": "",
        "updDt": "",
        "readKnt": "",
        "usrPwd": ""
    }];
    dlTemplate.setJSON(jsonData);
    return false;
    // 공통코드 세팅 {code:공통코드, compID:세팅할 컴포넌트, 그리드:컬럼}
    var arrJson = [{
        code: "C03261",
        compID: "gvTemplate:optCd"
    }]
    var promise = common.setComCode(arrJson);
    // 상단버튼 세팅 {id:"test", label:"test", icon:true, className:"blue", display:true, float:"left"}
    var arr = [];
    arr.push({
        "id": "link",
        "label": "link",
        "display": true,
        "float": "left",
        icon: true
    });
    arr.push({
        "id": "save",
        "label": "Save",
        "display": true,
        "float": "right",
        className: "blue"
    });
    arr.push({
        "id": "clear",
        "label": "Clear",
        "display": true,
        "float": "right",
        className: "blue"
    });
    udcTopBtns.setBtnDisplay(arr);
    // 상단버튼 show/hide
    //udcTopBtns.setBtnDisplay({id:"link", display:false});
};
scwin.onpageunload = function() {
    return false;
};
scwin.udcSrchBox_onRetrieveClick = function(e) {
    scwin.retrieve(this);
};
scwin.preRetrieve = function() {
    return Promise.resolve(true);
    return scwin.validateDetail("grpSrhbox");
};
scwin.retrieve = function(btn) {
    var promise = scwin.preRetrieve();
    promise = promise.then(function(res) {
        if (res) {
            var ref = [{
                "id": "dmSearch",
                "key": "dmSearch"
            }];
            var target = [{
                "id": "dlTemplate",
                "key": "dlTemplate"
            }];
            var opts = {
                useThen: true
            };
            var promise1 = common.execute(null,
                "/template/searchComEduBrdList.do", ref, target, null,
                btn, opts);
            promise1 = promise1.then(function(res) {
                if (window.common.isStatus(res)) {
                    $p.log("저장후 처리");
                }
            });
            return promise1;
        }
        return false;
    });
    return promise;
};
scwin.preSave = function() {
    return scwin.validateDetail("gvTemplate");
};
scwin.save = function(btn) {
    var promise = scwin.preSave();
    promise = promise
        .then(function(res) {
            if (res) {
                var promise1 = udcAttachM.executePromise(btn);
                promise1 = promise1
                    .then(function(res) {
                        if (res.data.length > 0) {
                            debugger;
                            dmDetail.set("cmtDesc", udcAttachM
                                .getFileSavId());
                            // dmDetail.set( "cmtDesc" , res.data[0]["fileSavId"] );
                        }
                        var ref = [{
                                "id": "dmSearch",
                                "key": "dmSearch"
                            },
                            {
                                "id": "dmDetail",
                                "key": "dmTemplate"
                            },
                            {
                                "id": udcAttachM.getDataList(),
                                "key": window.common["FILE_INFO"]["FILE_KEY"]
                            }
                        ];
                        var target = [{
                            "id": "dmDetail",
                            "key": "dmTemplate"
                        }, {
                            "id": udcAttachM.getDataList(),
                            "key": "dlAttachM"
                        }];
                        var opts = {
                            useThen: true
                        };
                        var promise2 = common.execute(null,
                            "/template/manageComEduBrd.do",
                            ref, target, null, btn, opts);
                        promise2 = promise2
                            .then(function(res) {
                                if (res["Common"]["status"] === window.common["STATUS_CODE"]["SUCCESS"]) {
                                    $p.log("저장후 처리");
                                    return common
                                        .alert("처리 되었습니다.");
                                }
                            });
                        return promise2;
                    });
                return promise1;
            }
            return false;
        });
    return promise;
};
scwin.udcTopBtns_onBtnClick = function(id, e) {
    if (id == "link") {
        var options = {
            popupName: "팝업샘플",
            width: 1000,
            height: 900
        };
        var promise = common.openPopup("com_popup1", options);
    } else if (id == "save") {
        scwin.save(this);
    } else if (id == "clear") {
        common.reload("dmSearch", "dlTemplate");
    }
};
scwin.gvTemplate_onrowstatusclick = function(row) {
    /*
     * 0번째 인덱스 removeRow 시 오류발생.
     */
    console.log("onrowstatusclick ", row);
    dlTemplate.removeRow(row);
};
scwin.trigger1_onclick = function(e) {
    dlTemplate.insertRow();
};
scwin.checkLog = function() {
    return WebSquare.logger.getErrorLog();
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플실행 후 첫번째 행을 삭제한다.

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gvTemplate_headerRowStatus_bodyRow_0').click()");	
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 에러발생여부를 확인한다.
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
